package com.fasterxml.jackson.databind.deser.impl;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.JsonDeserializer;
import com.fasterxml.jackson.databind.JsonMappingException;
import com.fasterxml.jackson.databind.deser.SettableBeanProperty;
import com.fasterxml.jackson.databind.deser.impl.BeanPropertyMap;
import com.fasterxml.jackson.databind.util.NameTransformer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.InvocationTargetException;
import java.math.*;
import java.util.*;
import java.util.Collections;
import org.junit.*;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

/**
 * Unit tests for BeanPropertyMap._rename method.
 * Since _rename is protected, we use a subclass to expose it for testing.
 */
public class BeanPropertyMap__rename_TriageGen1Test {

    private static class TestableBeanPropertyMap extends BeanPropertyMap {
        protected TestableBeanPropertyMap(boolean caseInsensitive, java.util.Collection<SettableBeanProperty> props) {
            super(caseInsensitive, props);
        }

        @Override
        public SettableBeanProperty _rename(SettableBeanProperty prop, NameTransformer xf) {
            return super._rename(prop, xf);
        }
    }

    public interface NameTransformer {
        String transform(String name);
    }

    @Test
    public void testRename_NullProperty() {
        TestableBeanPropertyMap map = new TestableBeanPropertyMap(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty result = map._rename(null, xf);

        assertNull(result);
    }

    @Test
    public void testRename_SimpleNameTransformation() {
        TestableBeanPropertyMap map = new TestableBeanPropertyMap(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        SettableBeanProperty renamedProp = mock(SettableBeanProperty.class);

        when(prop.getName()).thenReturn("oldName");
        when(xf.transform("oldName")).thenReturn("newName");
        when(prop.withSimpleName("newName")).thenReturn(renamedProp);
        // Return null for deserializer to cover the if (deser != null) branch
        when(renamedProp.getValueDeserializer()).thenReturn(null);

        SettableBeanProperty result = map._rename(prop, xf);

        assertEquals(renamedProp, result);
    }

    @Test
    public void testRename_WithDeserializerTransformation() {
        TestableBeanPropertyMap map = new TestableBeanPropertyMap(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        SettableBeanProperty renamedProp = mock(SettableBeanProperty.class);

        JsonDeserializer<?> originalDeser = mock(JsonDeserializer.class);
        JsonDeserializer<?> unwrappedDeser = mock(JsonDeserializer.class);

        when(prop.getName()).thenReturn("oldName");
        when(xf.transform("oldName")).thenReturn("newName");
        when(prop.withSimpleName("newName")).thenReturn(renamedProp);

        // Setup deserializer logic
        when(renamedProp.getValueDeserializer()).thenReturn(originalDeser);
        when(originalDeser.unwrappingDeserializer(xf)).thenReturn(unwrappedDeser);

        // Scenario: newDeser != deser
        when(renamedProp.withValueDeserializer(unwrappedDeser)).thenReturn(mock(SettableBeanProperty.class));

        SettableBeanProperty result = map._rename(prop, xf);

        // Verify that withValueDeserializer was called because they are different
        org.mockito.Mockito.verify(renamedProp).withValueDeserializer(unwrappedDeser);
        org.mockito.Mockito.verify(renamedProp).withSimpleName("newName");
    }

    @Test
    public void testRename_WithDeserializerSameInstance() {
        TestableBeanPropertyMap map = new TestableBeanPropertyMap(false, Collections.emptyList());
        NameTransformer xf = mock(NameTransformer.class);

        SettableBeanProperty prop = mock(SettableBeanProperty.class);
        SettableBeanProperty renamedProp = mock(SettableBeanProperty.class);

        JsonDeserializer<?> deser = mock(JsonDeserializer.class);

        when(prop.getName()).thenReturn("oldName");
        when(xf.transform("oldName")).thenReturn("newName");
        when(prop.withSimpleName("newName")).thenReturn(renamedProp);

        // Scenario: newDeser == deser
        when(renamedProp.getValueDeserializer()).thenReturn(deser);
        when(deser.unwrappingDeserializer(xf)).thenReturn(deser);

        SettableBeanProperty result = map._rename(prop, xf);

        // Verify that withValueDeserializer was NOT called because they are the same
        org.mockito.Mockito.verify(renamedProp, org.mockito.Mockito.never()).withValueDeserializer(org.mockito.ArgumentMatchers.any());
        assertEquals(renamedProp, result);
    }
}
